import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import {
    DollarSign, TrendingUp, PiggyBank, Clock,
    Briefcase, Percent
} from 'lucide-react';
import commissionService from '../../services/commissionService';
import StatusBadge from '../../components/datadisplay/StatusBadge';

const Earnings = () => {
    const [filter, setFilter] = useState('all');

    const { data, isLoading } = useQuery({
        queryKey: ['my-earnings', filter],
        queryFn: () => commissionService.getMyEarnings({
            status: filter === 'all' ? undefined : filter
        })
    });

    const config = data?.config;
    const summary = data?.summary;
    const recentEarnings = data?.recentEarnings || [];

    const earningsBreakdown = [
        { label: 'Commission', value: summary?.totalCommission || 0, color: 'text-indigo-600', icon: Percent },
        { label: 'Salary', value: summary?.totalSalary || 0, color: 'text-emerald-600', icon: Briefcase },
        { label: 'Pending', value: summary?.pendingEarnings || 0, color: 'text-amber-600', icon: Clock },
        { label: 'Paid', value: summary?.paidEarnings || 0, color: 'text-teal-600', icon: CheckCircle },
    ];

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">My Earnings</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Track your commissions and earnings
                </p>
            </div>

            {/* Commission Structure Card */}
            {config && (
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-gradient-to-r from-indigo-500 to-purple-600 rounded-xl p-6 text-white"
                >
                    <h3 className="text-lg font-semibold mb-3">Your Commission Structure</h3>
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                        <div className="bg-white/10 rounded-lg p-3">
                            <p className="text-sm text-indigo-100">Structure</p>
                            <p className="text-lg font-bold capitalize">
                                {config.structure.replace(/_/g, ' ')}
                            </p>
                        </div>

                        {config.baseSalary > 0 && (
                            <div className="bg-white/10 rounded-lg p-3">
                                <p className="text-sm text-indigo-100">Base Salary</p>
                                <p className="text-lg font-bold">
                                    ${config.baseSalary.toLocaleString()}/mo
                                </p>
                            </div>
                        )}

                        {config.commissionPercentage > 0 && (
                            <div className="bg-white/10 rounded-lg p-3">
                                <p className="text-sm text-indigo-100">Commission Rate</p>
                                <p className="text-lg font-bold">
                                    {config.commissionPercentage}%
                                </p>
                            </div>
                        )}
                    </div>
                </motion.div>
            )}

            {/* Earnings Overview */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {earningsBreakdown.map((item) => (
                    <motion.div
                        key={item.label}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700"
                    >
                        <div className="flex items-center gap-3 mb-2">
                            <item.icon className={`h-5 w-5 ${item.color}`} />
                            <span className="text-sm text-gray-500 dark:text-gray-400">{item.label}</span>
                        </div>
                        <p className="text-2xl font-bold text-gray-900 dark:text-white">
                            ${item.value.toLocaleString()}
                        </p>
                    </motion.div>
                ))}
            </div>

            {/* Recent Earnings */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.1 }}
                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700"
            >
                <div className="p-6 border-b border-gray-200 dark:border-gray-700">
                    <div className="flex items-center justify-between">
                        <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                            Recent Earnings
                        </h3>

                        <select
                            value={filter}
                            onChange={(e) => setFilter(e.target.value)}
                            className="px-3 py-1.5 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-300"
                        >
                            <option value="all">All</option>
                            <option value="pending">Pending</option>
                            <option value="paid">Paid</option>
                        </select>
                    </div>
                </div>

                <div className="divide-y divide-gray-200 dark:divide-gray-700">
                    {recentEarnings.length === 0 ? (
                        <div className="p-8 text-center text-gray-500">
                            <DollarSign className="h-12 w-12 mx-auto mb-3 text-gray-400" />
                            <p>No earnings yet</p>
                        </div>
                    ) : (
                        recentEarnings.map((earning) => (
                            <div key={earning.id} className="p-4 hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors">
                                <div className="flex items-center gap-4">
                                    <div className={`p-2 rounded-lg ${earning.type === 'commission'
                                        ? 'bg-indigo-100 dark:bg-indigo-900/30'
                                        : earning.type === 'salary'
                                            ? 'bg-emerald-100 dark:bg-emerald-900/30'
                                            : 'bg-amber-100 dark:bg-amber-900/30'
                                        }`}>
                                        <DollarSign className={`h-5 w-5 ${earning.type === 'commission'
                                            ? 'text-indigo-600 dark:text-indigo-400'
                                            : earning.type === 'salary'
                                                ? 'text-emerald-600 dark:text-emerald-400'
                                                : 'text-amber-600 dark:text-amber-400'
                                            }`} />
                                    </div>

                                    <div className="flex-1">
                                        <div className="flex items-center gap-2">
                                            <p className="font-medium text-gray-900 dark:text-white capitalize">
                                                {earning.type}
                                            </p>
                                            <StatusBadge status={earning.status} size="sm" />
                                        </div>
                                        <p className="text-sm text-gray-500 dark:text-gray-400">
                                            {earning.description}
                                        </p>
                                        {earning.productName && (
                                            <p className="text-xs text-gray-400">
                                                Product: {earning.productName}
                                            </p>
                                        )}
                                    </div>

                                    <div className="text-right">
                                        <p className="text-lg font-bold text-gray-900 dark:text-white">
                                            ${earning.amount.toFixed(2)}
                                        </p>
                                        <p className="text-xs text-gray-500">
                                            {new Date(earning.earnedAt || earning.createdAt).toLocaleDateString()}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </motion.div>
        </div>
    );
};

export default Earnings;
